package notify

import (
	"log/slog"
	"time"
)

//go:generate optgen generate --string-setter plain --source-file $GOFILE

// Defaults referenced from the optgen tags.
const (
	// DefaultPingInterval is how long the socket may stay silent.
	DefaultPingInterval = 30 * time.Second
	// DefaultPingTimeout is how long a ping may wait for its pong.
	DefaultPingTimeout = 10 * time.Second
)

// options are a [Stream]'s tunables. The With options are generated by
// go-optgen; a nil or non-positive argument keeps the default.
type options struct {
	// userAgent is the User-Agent on the upgrade. Empty sends no header.
	userAgent string `optgen:"manual"`

	// pingInterval is how long the socket may stay silent before a ping.
	pingInterval time.Duration `optgen:"default=DefaultPingInterval" optval:"positive"`

	// pingTimeout is how long a ping may wait for its pong. A socket that
	// does not answer in time is closed and dialed again: a connection that
	// died without a close never answers, and nothing else would notice.
	pingTimeout time.Duration `optgen:"default=DefaultPingTimeout" optval:"positive"`

	// log receives the stream's records. The default is slog.Default as it
	// stands when the stream is built.
	log *slog.Logger `opt:"Logger" optgen:"default=slog.Default()"`
}

// WithUserAgent sets the User-Agent. The empty string, a real choice, sends
// no header; go-optgen's string setter would skip it.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}
